          {k:"B", de:"ihre Kinder nicht so früh aufstehen können.", ar:"أطفالهم لن يتمكنوا من الاستيقاظ مبكرًا.", ma:"الدراري ديالهم ما يقدروش يفيقو بكري."},
          {k:"C", de:"ihre Kinder vor dem Computer Angst haben.", ar:"أطفالهم يخافون من الكمبيوتر.", ma:"الدراري ديالهم كيخافو من الكمبيوتر."}
